import re,glob,sys,collections
files=sorted(glob.glob('/tmp/r2run-jm59oyzo/data/text/*.txt'))
hdr=re.compile(r'finds the following violation',re.I)
cites=[]; issues=[]
for f in files:
    lines=open(f,encoding='utf-8',errors='replace').read().split('\n')
    n=0
    for i,l in enumerate(lines):
        if hdr.search(l):
            n+=1
            # find cite in next 6 lines
            found=None
            for j in range(i+1,min(i+8,len(lines))):
                if re.search(r'IC\s*8\s*-\s*[1lI]\s*-\s*26',lines[j]) or re.search(r'8-[1l]-26',lines[j]):
                    found=lines[j];break
            if found is None:
                issues.append((f,i,'nocite'));continue
            cites.append((f.split('/')[-1],found.strip()))
    if n==0: issues.append((f,0,'noheader'))
print(len(cites),len(issues))
for x in issues[:20]: print(x)
c=collections.Counter(s for _,s in cites)
for k,v in c.most_common(200): print(v,repr(k))
EOF
